'use strict';

/**
 * Bundled offline mock of the Arena Agent API.
 *
 * It speaks OpenAI-compatible /v1/chat/completions (streaming + non-streaming)
 * and drives a small scripted "brain" that demonstrates the full agent loop:
 * plan → create files → verify with a shell command → mark plan done → summary.
 *
 * Used by `arena --mock`, the demo script and the e2e smoke test.
 */

const http = require('http');

const AUTH_FILE = 'src/auth.js';
const AUTH_TEST_CMD = `node -e "const a=require('./src/auth'); const t=a.register('kai','s3cret'); const ok=a.verify(t); console.log('auth check:', ok ? 'PASS' : 'FAIL');"`;

const AUTH_MODULE = `'use strict';

const crypto = require('crypto');

// Minimal in-memory auth module generated by Arena Agent (mock demo).
const users = new Map();   // username -> { salt, hash }
const tokens = new Map();  // token -> username

function hash(password, salt) {
  return crypto.scryptSync(password, salt, 32).toString('hex');
}

function register(username, password) {
  if (!username || !password) throw new Error('username and password are required');
  if (users.has(username)) throw new Error('user already exists: ' + username);
  const salt = crypto.randomBytes(16).toString('hex');
  users.set(username, { salt, hash: hash(password, salt) });
  return issueToken(username);
}

function login(username, password) {
  const u = users.get(username);
  if (!u) return null;
  if (hash(password, u.salt) !== u.hash) return null;
  return issueToken(username);
}

function issueToken(username) {
  const token = crypto.randomBytes(24).toString('base64url');
  tokens.set(token, username);
  return token;
}

function verify(token) {
  return tokens.has(token) ? { username: tokens.get(token) } : null;
}

function logout(token) {
  return tokens.delete(token);
}

module.exports = { register, login, verify, logout };
`;

function taskEcho(messages) {
  const lastUser = [...messages].reverse().find((m) => m.role === 'user' && typeof m.content === 'string');
  return lastUser ? String(lastUser.content).slice(0, 120).replace(/\n/g, ' ') : '(no task)';
}

function pickSpec(step, task) {
  switch (step) {
    case 0:
      return {
        tool: 'update_plan',
        input: {
          todos: [
            { content: `Understand task: ${task}`, status: 'done' },
            { content: 'Implement auth module (src/auth.js)', status: 'in_progress' },
            { content: 'Verify with a smoke test', status: 'pending' },
          ],
        },
      };
    case 1:
      return { tool: 'write_file', input: { path: AUTH_FILE, content: AUTH_MODULE } };
    case 2:
      return { tool: 'run_command', input: { command: AUTH_TEST_CMD, description: 'smoke-test the auth module' } };
    case 3:
      return {
        tool: 'update_plan',
        input: {
          todos: [
            { content: `Understand task: ${task}`, status: 'done' },
            { content: 'Implement auth module (src/auth.js)', status: 'done' },
            { content: 'Verify with a smoke test', status: 'done' },
          ],
        },
      };
    default:
      return {
        text:
          `Done. I added a small authentication module for the task: "${task}".\n\n` +
          'What changed:\n' +
          `- Created ${AUTH_FILE} with register/login/verify/logout backed by crypto.scrypt password hashing and opaque session tokens.\n\n` +
          'Verification:\n' +
          '- Ran a smoke test that registers a user, verifies the issued token, and printed `auth check: PASS`.\n\n' +
          'Next steps you may want: wire the module into your HTTP routes, add persistent storage, and add real tests. (Note: this reply came from the bundled offline mock — point ARENA_BASE_URL/Arena_API_KEY at the real Arena Agent API for full intelligence.)',
      };
  }
}

function pickResponse(messages) {
  const step = messages.filter((m) => m.role === 'tool').length;
  const task = taskEcho(messages);
  const spec = pickSpec(step, task);
  if (spec.text) return { content: spec.text };
  return {
    tool_calls: [
      {
        id: `mock_call_${spec.tool}_${step}`,
        type: 'function',
        function: { name: spec.tool, arguments: JSON.stringify(spec.input) },
      },
    ],
  };
}

/* ---------------- Anthropic Messages API (/v1/messages) ------------- */

function countAnthropicToolResults(messages) {
  let n = 0;
  for (const m of messages || []) {
    if (Array.isArray(m.content)) {
      for (const b of m.content) if (b && b.type === 'tool_result') n++;
    }
  }
  return n;
}

function anthropicTaskEcho(messages) {
  for (const m of messages || []) {
    if (m.role === 'user' && typeof m.content === 'string' && m.content.trim()) {
      return String(m.content).slice(0, 120).replace(/\n/g, ' ');
    }
  }
  return '(no task)';
}

function anthropicMessage(spec) {
  const content = [];
  if (spec.text) content.push({ type: 'text', text: spec.text });
  if (spec.tool) {
    content.push({ type: 'tool_use', id: `mock_tool_${spec.tool}`, name: spec.tool, input: spec.input });
  }
  return content;
}

function anthropicEvents(content, model) {
  const events = [];
  events.push({
    type: 'message_start',
    message: { id: 'mock_msg', type: 'message', role: 'assistant', model, content: [], stop_reason: null, usage: { input_tokens: 1200, output_tokens: 1 } },
  });
  content.forEach((block, index) => {
    events.push({ type: 'content_block_start', index, content_block: block.type === 'text' ? { type: 'text', text: '' } : { type: 'tool_use', id: block.id, name: block.name, input: {} } });
    if (block.type === 'text') {
      for (let i = 0; i < block.text.length; i += 14) {
        events.push({ type: 'content_block_delta', index, delta: { type: 'text_delta', text: block.text.slice(i, i + 14) } });
      }
    } else {
      const js = JSON.stringify(block.input);
      for (let i = 0; i < js.length; i += 48) {
        events.push({ type: 'content_block_delta', index, delta: { type: 'input_json_delta', partial_json: js.slice(i, i + 48) } });
      }
    }
    events.push({ type: 'content_block_stop', index });
  });
  const stopReason = content.some((b) => b.type === 'tool_use') ? 'tool_use' : 'end_turn';
  events.push({ type: 'message_delta', delta: { stop_reason: stopReason }, usage: { output_tokens: 90 } });
  events.push({ type: 'message_stop' });
  return events;
}

/* ------------------------------------------------------------------ */

function messageToEvents(msg) {
  const events = [];
  events.push({ choices: [{ index: 0, delta: { role: 'assistant' }, finish_reason: null }] });

  if (msg.content) {
    const pieces = [];
    for (let i = 0; i < msg.content.length; i += 14) pieces.push(msg.content.slice(i, i + 14));
    for (const p of pieces) events.push({ choices: [{ index: 0, delta: { content: p }, finish_reason: null }] });
    events.push({ choices: [{ index: 0, delta: {}, finish_reason: 'stop' }] });
  }

  if (msg.tool_calls && msg.tool_calls.length) {
    msg.tool_calls.forEach((tc, i) => {
      events.push({
        choices: [
          {
            index: 0,
            delta: { tool_calls: [{ index: i, id: tc.id, type: 'function', function: { name: tc.function.name, arguments: '' } }] },
            finish_reason: null,
          },
        ],
      });
      const args = tc.function.arguments;
      for (let j = 0; j < args.length; j += 48) {
        events.push({
          choices: [
            { index: 0, delta: { tool_calls: [{ index: i, function: { arguments: args.slice(j, j + 48) } }] }, finish_reason: null },
          ],
        });
      }
    });
    events.push({ choices: [{ index: 0, delta: {}, finish_reason: 'tool_calls' }] });
  }

  events.push({ usage: { prompt_tokens: 1200, completion_tokens: 90, total_tokens: 1290 } });
  return events;
}

function startMockServer(port = 0) {
  // Device-flow state (auto-approves after a couple of polls so scripted
  // runs complete without a human in the browser).
  const device = { code: null, userCode: null, polls: 0 };

  const server = http.createServer((req, res) => {
    /* ---------------- OAuth device flow ---------------- */
    if (req.method === 'POST' && req.url === '/oauth/device/code') {
      device.code = 'mock-device-' + Date.now();
      device.userCode = 'ARENA-' + Math.random().toString(36).slice(2, 6).toUpperCase();
      device.polls = 0;
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end(
        JSON.stringify({
          device_code: device.code,
          user_code: device.userCode,
          verification_uri: `http://127.0.0.1:${server.address().port}/activate`,
          verification_uri_complete: `http://127.0.0.1:${server.address().port}/activate?code=${device.userCode}`,
          interval: 1,
          expires_in: 300,
        })
      );
      return;
    }

    if (req.method === 'POST' && req.url === '/oauth/token') {
      let body = '';
      req.on('data', (d) => (body += d));
      req.on('end', () => {
        let parsed;
        try {
          parsed = JSON.parse(body || '{}');
        } catch {
          parsed = {};
        }
        const json = (status, obj) => {
          res.writeHead(status, { 'content-type': 'application/json' });
          res.end(JSON.stringify(obj));
        };
        if (parsed.grant_type === 'refresh_token') {
          return json(200, { access_token: 'mock-refreshed-token', token_type: 'Bearer', expires_in: 3600 });
        }
        if (parsed.grant_type !== 'urn:ietf:params:oauth:grant-type:device_code' || parsed.device_code !== device.code) {
          return json(400, { error: 'invalid_grant' });
        }
        device.polls++;
        if (device.polls < 2) {
          return json(400, { error: 'authorization_pending' });
        }
        json(200, {
          access_token: 'mock-access-token',
          refresh_token: 'mock-refresh-token',
          token_type: 'Bearer',
          expires_in: 3600,
          account: { email: 'dev@arena.ai', name: 'Arena Developer', plan: 'pro' },
        });
      });
      return;
    }

    if (req.method === 'GET' && req.url.startsWith('/activate')) {
      res.writeHead(200, { 'content-type': 'text/html' });
      res.end(
        `<html><body style="font-family:sans-serif;padding:3rem;background:#111;color:#eee">
           <h2 style="color:#a78bfa">◆ Arena AI — device activation</h2>
           <p>Mock activation page. The CLI auto-approves after a couple of seconds.</p>
           <p>Code: <b>${device.userCode || '(none issued yet)'}</b></p>
         </body></html>`
      );
      return;
    }

    if (req.method === 'GET' && req.url === '/me') {
      const auth = req.headers.authorization || '';
      if (!auth.startsWith('Bearer ')) {
        res.writeHead(401, { 'content-type': 'application/json' });
        res.end(JSON.stringify({ error: 'unauthorized' }));
        return;
      }
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end(JSON.stringify({ email: 'dev@arena.ai', name: 'Arena Developer', plan: 'pro' }));
      return;
    }

    if (req.method === 'POST' && req.url === '/v1/messages') {
      let body = '';
      req.on('data', (d) => (body += d));
      req.on('end', () => {
        let parsed;
        try {
          parsed = JSON.parse(body || '{}');
        } catch {
          res.writeHead(400, { 'content-type': 'application/json' });
          res.end(JSON.stringify({ type: 'error', error: { message: 'bad JSON' } }));
          return;
        }
        const step = countAnthropicToolResults(parsed.messages);
        const task = anthropicTaskEcho(parsed.messages);
        const spec = pickSpec(step, task);
        const content = anthropicMessage(spec);
        const model = parsed.model || 'coding-router-preview';
        const finish = content.some((b) => b.type === 'tool_use') ? 'tool_use' : 'end_turn';

        if (!parsed.stream) {
          res.writeHead(200, { 'content-type': 'application/json' });
          res.end(
            JSON.stringify({
              id: 'mock-msg-' + Date.now(),
              type: 'message',
              role: 'assistant',
              model,
              content,
              stop_reason: finish,
              usage: { input_tokens: 1200, output_tokens: 90 },
            })
          );
          return;
        }
        res.writeHead(200, { 'content-type': 'text/event-stream', 'cache-control': 'no-cache' });
        const events = anthropicEvents(content, model);
        let i = 0;
        const timer = setInterval(() => {
          if (i >= events.length) {
            clearInterval(timer);
            res.end();
            return;
          }
          const ev = events[i++];
          res.write(`event: ${ev.type}\ndata: ${JSON.stringify(ev)}\n\n`);
        }, 5);
      });
      return;
    }

    if (req.method === 'GET' && req.url === '/v1/models') {
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end(JSON.stringify({ data: [{ id: 'arena-agent' }, { id: 'arena-agent-fast' }, { id: 'arena-agent-mini' }] }));
      return;
    }
    if (req.method === 'POST' && req.url === '/v1/chat/completions') {
      let body = '';
      req.on('data', (d) => (body += d));
      req.on('end', () => {
        let parsed;
        try {
          parsed = JSON.parse(body || '{}');
        } catch {
          res.writeHead(400, { 'content-type': 'application/json' });
          res.end(JSON.stringify({ error: { message: 'bad JSON' } }));
          return;
        }
        const msg = pickResponse(parsed.messages || []);
        if (!parsed.stream) {
          res.writeHead(200, { 'content-type': 'application/json' });
          res.end(
            JSON.stringify({
              id: 'mock-' + Date.now(),
              choices: [{ index: 0, message: { role: 'assistant', ...msg }, finish_reason: msg.tool_calls ? 'tool_calls' : 'stop' }],
              usage: { prompt_tokens: 1200, completion_tokens: 90, total_tokens: 1290 },
            })
          );
          return;
        }
        res.writeHead(200, { 'content-type': 'text/event-stream', 'cache-control': 'no-cache' });
        const events = messageToEvents(msg);
        let i = 0;
        const timer = setInterval(() => {
          if (i >= events.length) {
            res.write('data: [DONE]\n\n');
            clearInterval(timer);
            res.end();
            return;
          }
          res.write(`data: ${JSON.stringify(events[i++])}\n\n`);
        }, 8);
      });
      return;
    }
    res.writeHead(404, { 'content-type': 'application/json' });
    res.end(JSON.stringify({ error: { message: 'not found' } }));
  });

  return new Promise((resolve, reject) => {
    server.on('error', reject);
    server.listen(port, '127.0.0.1', () => {
      resolve({
        port: server.address().port,
        url: `http://127.0.0.1:${server.address().port}`,
        close: () => new Promise((r) => server.close(r)),
      });
    });
  });
}

module.exports = { startMockServer };

if (require.main === module) {
  const port = Number(process.argv[2] || 8420);
  startMockServer(port).then((s) => {
    console.log(`mock Arena Agent API on ${s.url}/v1`);
  });
}
